/// One entry in the canonical vocabulary, pairing a stored value with its
/// display label and its illustration.
///
/// Deliberately named `CategoryArt` rather than `Category`: the app also has a
/// Firestore-backed `Category` model in `lib/models/category.dart`, and two
/// same-named classes in one import graph is a constant source of ambiguous
/// imports.
///
/// The SVGs are generated by tool/generate_category_art.py.
class CategoryArt {
  const CategoryArt({
    required this.value,
    required this.label,
    required this.asset,
  });

  /// Canonical stored value, lowercase.
  final String value;

  /// Human-readable label for UI.
  final String label;

  /// Path to the illustration, relative to the asset root.
  final String asset;
}

class AppCategories {
  const AppCategories._();

  /// The canonical vocabulary. This is the single source of truth: artwork,
  /// labels and the category chips all derive from it, so a category added
  /// here appears everywhere and nowhere silently breaks.
  static const List<CategoryArt> catalog = [
    CategoryArt(value: 'anime', label: 'Anime', asset: 'assets/categories/anime.svg'),
    CategoryArt(value: 'donghua', label: 'Donghua', asset: 'assets/categories/donghua.svg'),
    CategoryArt(value: 'manga', label: 'Manga', asset: 'assets/categories/manga.svg'),
    CategoryArt(value: 'manhua', label: 'Manhua', asset: 'assets/categories/manhua.svg'),
    CategoryArt(value: 'manhwa', label: 'Manhwa', asset: 'assets/categories/manhwa.svg'),
    CategoryArt(value: 'comics', label: 'Comics', asset: 'assets/categories/comics.svg'),
    CategoryArt(value: 'gaming', label: 'Gaming', asset: 'assets/categories/gaming.svg'),
    CategoryArt(value: 'e-sports', label: 'E-sports', asset: 'assets/categories/e-sports.svg'),
    CategoryArt(value: 'music', label: 'Music', asset: 'assets/categories/music.svg'),
    CategoryArt(value: 'movies', label: 'Movies', asset: 'assets/categories/movies.svg'),
    CategoryArt(value: 'books', label: 'Books', asset: 'assets/categories/books.svg'),
  ];

  /// Just the stored values, which is what queries and filters compare against.
  static List<String> get all => catalog.map((c) => c.value).toList(growable: false);

  /// Looks up a category, tolerating legacy Title Case values.
  static CategoryArt? find(String value) {
    final needle = value.trim().toLowerCase();
    for (final category in catalog) {
      if (category.value == needle) return category;
    }
    return null;
  }

  /// UI label for a stored value, falling back to a title-cased form for a
  /// value that is not in the vocabulary.
  static String label(String category) {
    final trimmed = category.trim();
    if (trimmed.isEmpty) return trimmed;
    return find(trimmed)?.label ?? _titleCase(trimmed);
  }

  /// Illustration for a stored value, or null when the category is unknown.
  static String? artAssetFor(String category) => find(category)?.asset;

  /// True if [value] is in the canonical vocabulary.
  static bool isValid(String value) => find(value) != null;

  /// Normalises any casing to the canonical stored form. Use on every value
  /// before writing to Firestore or building a query.
  static String normalize(String value) => value.trim().toLowerCase();

  static String _titleCase(String value) =>
      value.isEmpty ? value : value[0].toUpperCase() + value.substring(1);
}
